    doc = nlp(text)
    noun_count = sum(1 for token in doc if token.pos_ == 'NOUN')
    total_word_count = len(doc)
    return float(noun_count) / total_word_count if total_word_count > 0 else 0.0

def feature(text: str) -> float:
